-- MySQL 8.0+ / utf8mb4. UUIDs are generated by the application as CHAR(36).
create database if not exists bader_property_management character set utf8mb4 collate utf8mb4_0900_ai_ci;
use bader_property_management;

create table organizations (id char(36) primary key, name varchar(200) not null, timezone varchar(64) not null default 'Asia/Riyadh', default_currency char(3) not null default 'SAR', created_at datetime(3) not null default current_timestamp(3)) engine=InnoDB;
create table users (id char(36) primary key, organization_id char(36) not null, full_name varchar(200) not null, email varchar(255) not null, password_hash varchar(255) not null, status enum('active','inactive','archived') not null default 'active', unique key uq_user_email(organization_id,email), foreign key(organization_id) references organizations(id)) engine=InnoDB;
create table owners (id char(36) primary key, organization_id char(36) not null, code varchar(50) not null, full_name varchar(200) not null, national_id_or_iqama varchar(50) not null, mobile varchar(30) not null, email varchar(255), city varchar(100) not null, district varchar(100), status enum('active','inactive','archived') not null default 'active', unique key uq_owner_code(organization_id,code), unique key uq_owner_identity(organization_id,national_id_or_iqama), foreign key(organization_id) references organizations(id)) engine=InnoDB;
create table owner_bank_accounts (id char(36) primary key, organization_id char(36) not null, owner_id char(36) not null, bank_name varchar(150) not null, iban varchar(34) not null, account_holder_name varchar(200) not null, is_default boolean not null default false, status enum('active','inactive','archived') not null default 'active', unique key uq_owner_iban(organization_id,iban), foreign key(organization_id) references organizations(id), foreign key(owner_id) references owners(id)) engine=InnoDB;
create table properties (id char(36) primary key, organization_id char(36) not null, owner_id char(36) not null, code varchar(50) not null, name varchar(200) not null, property_type varchar(80) not null, deed_number varchar(100), city varchar(100) not null, district varchar(100) not null, address json, status enum('active','inactive','archived') not null default 'active', unique key uq_property_code(organization_id,code), foreign key(organization_id) references organizations(id), foreign key(owner_id) references owners(id)) engine=InnoDB;
create table property_spaces (id char(36) primary key, organization_id char(36) not null, property_id char(36) not null, parent_space_id char(36), code varchar(50) not null, name varchar(200) not null, space_type enum('unit','floor','whole_property') not null, floor varchar(50), area decimal(12,2), status enum('active','inactive','archived','maintenance') not null default 'active', unique key uq_space_code(property_id,code), foreign key(organization_id) references organizations(id), foreign key(property_id) references properties(id), foreign key(parent_space_id) references property_spaces(id)) engine=InnoDB;
create table tenants (id char(36) primary key, organization_id char(36) not null, code varchar(50) not null, full_name varchar(200) not null, national_id_or_iqama varchar(50) not null, mobile varchar(30) not null, email varchar(255), status enum('active','inactive','archived') not null default 'active', unique key uq_tenant_code(organization_id,code), unique key uq_tenant_identity(organization_id,national_id_or_iqama), foreign key(organization_id) references organizations(id)) engine=InnoDB;
create table leases (id char(36) primary key, organization_id char(36) not null, internal_number varchar(80) not null, ejar_number varchar(100), tenant_id char(36) not null, start_date date not null, end_date date not null, annual_rent decimal(18,2) not null, total_value decimal(18,2) not null, currency char(3) not null default 'SAR', frequency enum('annual','semi_annual','quarterly','monthly','one_time','custom') not null, status enum('draft','active','expired','terminated','cancelled','renewed') not null default 'draft', unique key uq_lease_number(organization_id,internal_number), foreign key(organization_id) references organizations(id), foreign key(tenant_id) references tenants(id), check(end_date > start_date), check(annual_rent > 0 and total_value > 0)) engine=InnoDB;
create table lease_spaces (lease_id char(36) not null, property_space_id char(36) not null, start_date date not null, end_date date not null, primary key(lease_id,property_space_id), key ix_space_period(property_space_id,start_date,end_date), foreign key(lease_id) references leases(id) on delete cascade, foreign key(property_space_id) references property_spaces(id)) engine=InnoDB;
create table lease_installments (id char(36) primary key, lease_id char(36) not null, sequence_no int not null, due_date date not null, original_amount decimal(18,2) not null, notes text, unique key uq_installment(lease_id,sequence_no), foreign key(lease_id) references leases(id) on delete cascade, check(original_amount > 0)) engine=InnoDB;
create table receivables (id char(36) primary key, organization_id char(36) not null, installment_id char(36) not null unique, tenant_id char(36) not null, due_date date not null, original_amount decimal(18,2) not null, cancelled_at datetime(3), cancellation_reason text, key ix_receivable_due(organization_id,due_date), foreign key(organization_id) references organizations(id), foreign key(installment_id) references lease_installments(id), foreign key(tenant_id) references tenants(id), check(original_amount > 0)) engine=InnoDB;
create table payments (id char(36) primary key, organization_id char(36) not null, number varchar(80) not null, tenant_id char(36) not null, receipt_date date not null, posting_date date, method enum('bank_transfer','cash','cheque','card','other') not null, amount decimal(18,2) not null, transaction_reference varchar(150), status enum('draft','confirmed','reversed') not null default 'draft', idempotency_key varchar(100) not null, created_by char(36), created_at datetime(3) not null default current_timestamp(3), unique key uq_payment_number(organization_id,number), unique key uq_payment_idempotency(organization_id,idempotency_key), foreign key(organization_id) references organizations(id), foreign key(tenant_id) references tenants(id), foreign key(created_by) references users(id), check(amount > 0)) engine=InnoDB;
create table payment_allocations (id char(36) primary key, payment_id char(36) not null, receivable_id char(36) not null, amount decimal(18,2) not null, unique key uq_payment_receivable(payment_id,receivable_id), foreign key(payment_id) references payments(id), foreign key(receivable_id) references receivables(id), check(amount > 0)) engine=InnoDB;

create table company_bank_accounts (id char(36) primary key, organization_id char(36) not null, bank_name varchar(150) not null, account_name varchar(200) not null, iban varchar(34) not null, status enum('active','inactive','archived') not null default 'active', unique key uq_company_iban(organization_id,iban), foreign key(organization_id) references organizations(id)) engine=InnoDB;
create table bank_transactions (id char(36) primary key, organization_id char(36) not null, bank_account_id char(36) not null, booked_date date not null, value_date date, amount decimal(18,2) not null, direction enum('inbound','outbound') not null, external_reference varchar(150) not null, status enum('unmatched','partially_matched','matched') not null default 'unmatched', unique key uq_bank_reference(bank_account_id,external_reference), foreign key(organization_id) references organizations(id), foreign key(bank_account_id) references company_bank_accounts(id), check(amount>0)) engine=InnoDB;
create table expenses (id char(36) primary key, organization_id char(36) not null, property_id char(36) not null, space_id char(36), owner_id char(36), vendor_name varchar(200), description text not null, category varchar(80) not null, net_amount decimal(18,2) not null, vat_amount decimal(18,2) not null default 0, gross_amount decimal(18,2) not null, expense_date date not null, invoice_number varchar(100), chargeable_to_owner boolean not null default false, approval_status enum('not_required','pending','approved','rejected') not null default 'not_required', status enum('draft','confirmed','cancelled') not null default 'draft', foreign key(organization_id) references organizations(id), foreign key(property_id) references properties(id), foreign key(space_id) references property_spaces(id), foreign key(owner_id) references owners(id)) engine=InnoDB;
create table maintenance_requests (id char(36) primary key, organization_id char(36) not null, property_id char(36) not null, space_id char(36) not null, owner_id char(36), title varchar(255) not null, description text, priority enum('low','medium','high','urgent') not null default 'medium', estimated_cost decimal(18,2) not null default 0, actual_cost decimal(18,2), requires_owner_approval boolean not null default false, approval_status enum('not_required','pending','approved','rejected') not null default 'not_required', status enum('draft','active','confirmed','cancelled') not null default 'draft', foreign key(organization_id) references organizations(id), foreign key(property_id) references properties(id), foreign key(space_id) references property_spaces(id), foreign key(owner_id) references owners(id)) engine=InnoDB;
create table management_contracts (id char(36) primary key, organization_id char(36) not null, owner_id char(36) not null, number varchar(80) not null, start_date date not null, end_date date not null, fee_method enum('percentage_of_collections','fixed','hybrid','custom') not null, percent_rate decimal(7,4), fixed_amount decimal(18,2), approval_threshold decimal(18,2), status enum('draft','active','expired','terminated','cancelled') not null default 'draft', unique key uq_management_number(organization_id,number), foreign key(organization_id) references organizations(id), foreign key(owner_id) references owners(id), check(end_date>start_date)) engine=InnoDB;
create table owner_settlements (id char(36) primary key, organization_id char(36) not null, owner_id char(36) not null, number varchar(80) not null, period_start date not null, period_end date not null, gross_collections decimal(18,2) not null, management_fees decimal(18,2) not null, owner_expenses decimal(18,2) not null, adjustments decimal(18,2) not null, net_due decimal(18,2) not null, transfer_amount decimal(18,2) not null default 0, remaining_balance decimal(18,2) not null, status enum('draft','confirmed','voided') not null default 'draft', unique key uq_settlement_number(organization_id,number), foreign key(organization_id) references organizations(id), foreign key(owner_id) references owners(id), check(period_end>=period_start)) engine=InnoDB;
create table owner_transfers (id char(36) primary key, settlement_id char(36) not null, owner_bank_account_id char(36), transfer_date date not null, amount decimal(18,2) not null, transaction_reference varchar(150) not null, status enum('draft','confirmed','reversed') not null default 'confirmed', foreign key(settlement_id) references owner_settlements(id), foreign key(owner_bank_account_id) references owner_bank_accounts(id), check(amount>0)) engine=InnoDB;
create table bank_matches (id char(36) primary key, bank_transaction_id char(36) not null, payment_id char(36), owner_transfer_id char(36), amount decimal(18,2) not null, matched_by char(36), matched_at datetime(3) not null default current_timestamp(3), foreign key(bank_transaction_id) references bank_transactions(id), foreign key(payment_id) references payments(id), foreign key(owner_transfer_id) references owner_transfers(id), foreign key(matched_by) references users(id), check(amount>0)) engine=InnoDB;
create table attachments (id char(36) primary key, organization_id char(36) not null, entity_type varchar(80) not null, entity_id char(36) not null, storage_key varchar(500) not null, filename varchar(255) not null, mime_type varchar(100), bytes bigint unsigned, checksum varchar(128), uploaded_by char(36), uploaded_at datetime(3) not null default current_timestamp(3), foreign key(organization_id) references organizations(id), foreign key(uploaded_by) references users(id)) engine=InnoDB;
create table document_templates (id char(36) primary key, organization_id char(36) not null, template_key varchar(100) not null, name varchar(200) not null, category varchar(80) not null, locale varchar(10) not null default 'ar', active boolean not null default true, unique key uq_template_key(organization_id,template_key,locale), foreign key(organization_id) references organizations(id)) engine=InnoDB;
create table document_template_versions (id char(36) primary key, template_id char(36) not null, version_no int not null, body longtext not null, published_at datetime(3), unique key uq_template_version(template_id,version_no), foreign key(template_id) references document_templates(id)) engine=InnoDB;
create table generated_documents (id char(36) primary key, organization_id char(36) not null, template_version_id char(36), entity_type varchar(80) not null, entity_id char(36) not null, rendered_body longtext not null, storage_key varchar(500), status enum('draft','generated','sent') not null default 'draft', generated_by char(36), generated_at datetime(3) not null default current_timestamp(3), foreign key(organization_id) references organizations(id), foreign key(template_version_id) references document_template_versions(id), foreign key(generated_by) references users(id)) engine=InnoDB;
create table collection_follow_ups (id char(36) primary key, organization_id char(36) not null, receivable_id char(36) not null, document_id char(36), channel enum('email','sms','whatsapp','manual') not null, scheduled_at datetime(3) not null, status enum('draft','queued','sent','failed','cancelled') not null default 'draft', rendered_body longtext not null, foreign key(organization_id) references organizations(id), foreign key(receivable_id) references receivables(id), foreign key(document_id) references generated_documents(id)) engine=InnoDB;
create table communication_logs (id char(36) primary key, follow_up_id char(36) not null, provider varchar(80), recipient varchar(255) not null, provider_message_id varchar(150), status enum('queued','sent','failed') not null, sent_at datetime(3), failure_reason text, foreign key(follow_up_id) references collection_follow_ups(id)) engine=InnoDB;
create table audit_logs (id char(36) primary key, organization_id char(36) not null, actor_id char(36), action varchar(100) not null, entity_type varchar(80) not null, entity_id char(36) not null, before_json json, after_json json, request_id char(36), created_at datetime(3) not null default current_timestamp(3), foreign key(organization_id) references organizations(id), foreign key(actor_id) references users(id)) engine=InnoDB;

-- RBAC (G0)
create table roles (id char(36) primary key, organization_id char(36) not null, code varchar(80) not null, name varchar(150) not null, is_system boolean not null default false, unique key uq_role_code(organization_id,code), foreign key(organization_id) references organizations(id)) engine=InnoDB;
create table permissions (id char(36) primary key, code varchar(120) not null unique, name varchar(200) not null, module varchar(80) not null) engine=InnoDB;
create table user_roles (user_id char(36) not null, role_id char(36) not null, primary key(user_id,role_id), foreign key(user_id) references users(id), foreign key(role_id) references roles(id)) engine=InnoDB;
create table role_permissions (role_id char(36) not null, permission_id char(36) not null, primary key(role_id,permission_id), foreign key(role_id) references roles(id), foreign key(permission_id) references permissions(id)) engine=InnoDB;

-- Contract scope and approval rules (G3)
create table management_contract_scopes (id char(36) primary key, management_contract_id char(36) not null, property_id char(36) not null, space_id char(36), unique key uq_management_scope(management_contract_id,property_id,space_id), foreign key(management_contract_id) references management_contracts(id), foreign key(property_id) references properties(id), foreign key(space_id) references property_spaces(id)) engine=InnoDB;
create table management_contract_services (id char(36) primary key, management_contract_id char(36) not null, service_code varchar(100) not null, notes text, unique key uq_management_service(management_contract_id,service_code), foreign key(management_contract_id) references management_contracts(id)) engine=InnoDB;
create table management_contract_exclusions (id char(36) primary key, management_contract_id char(36) not null, exclusion_code varchar(100) not null, notes text, unique key uq_management_exclusion(management_contract_id,exclusion_code), foreign key(management_contract_id) references management_contracts(id)) engine=InnoDB;

-- Vendors, approvals and maintenance work (G6)
create table vendors (id char(36) primary key, organization_id char(36) not null, code varchar(50) not null, name varchar(200) not null, mobile varchar(30), email varchar(255), tax_number varchar(80), status enum('active','inactive','archived') not null default 'active', unique key uq_vendor_code(organization_id,code), foreign key(organization_id) references organizations(id)) engine=InnoDB;
alter table expenses add column vendor_id char(36) null after owner_id, add constraint fk_expense_vendor foreign key(vendor_id) references vendors(id);
create table expense_approvals (id char(36) primary key, expense_id char(36) not null, decision enum('submitted','approved','rejected') not null, decided_by char(36), reason text, decided_at datetime(3) not null default current_timestamp(3), foreign key(expense_id) references expenses(id), foreign key(decided_by) references users(id)) engine=InnoDB;
create table maintenance_work_orders (id char(36) primary key, maintenance_request_id char(36) not null, vendor_id char(36), assigned_by char(36), assigned_at datetime(3), started_at datetime(3), completed_at datetime(3), quoted_amount decimal(18,2), actual_amount decimal(18,2), status enum('draft','assigned','in_progress','completed','cancelled') not null default 'draft', foreign key(maintenance_request_id) references maintenance_requests(id), foreign key(vendor_id) references vendors(id), foreign key(assigned_by) references users(id)) engine=InnoDB;
create table maintenance_approvals (id char(36) primary key, maintenance_request_id char(36) not null, decision enum('submitted','approved','rejected') not null, decided_by char(36), reason text, decided_at datetime(3) not null default current_timestamp(3), foreign key(maintenance_request_id) references maintenance_requests(id), foreign key(decided_by) references users(id)) engine=InnoDB;

-- Immutable settlement composition (G7)
create table owner_settlement_payment_items (id char(36) primary key, settlement_id char(36) not null, payment_id char(36) not null, allocated_amount decimal(18,2) not null, fee_amount decimal(18,2) not null default 0, unique key uq_settlement_payment(settlement_id,payment_id), foreign key(settlement_id) references owner_settlements(id), foreign key(payment_id) references payments(id), check(allocated_amount > 0)) engine=InnoDB;
create table owner_settlement_expense_items (id char(36) primary key, settlement_id char(36) not null, expense_id char(36) not null, allocated_amount decimal(18,2) not null, unique key uq_settlement_expense(settlement_id,expense_id), foreign key(settlement_id) references owner_settlements(id), foreign key(expense_id) references expenses(id), check(allocated_amount > 0)) engine=InnoDB;
create table owner_settlement_adjustments (id char(36) primary key, settlement_id char(36) not null, adjustment_type enum('manual','rounding','correction') not null, amount decimal(18,2) not null, reason varchar(500) not null, created_by char(36), created_at datetime(3) not null default current_timestamp(3), foreign key(settlement_id) references owner_settlements(id), foreign key(created_by) references users(id), check(amount <> 0)) engine=InnoDB;
alter table owner_transfers add column source_company_bank_account_id char(36) null after owner_bank_account_id, add constraint fk_owner_transfer_source_account foreign key(source_company_bank_account_id) references company_bank_accounts(id);

-- Reminders, in-app notifications and organization configuration (G8/G9)
create table reminders (id char(36) primary key, organization_id char(36) not null, title varchar(255) not null, entity_type varchar(80), entity_id char(36), recipient_user_id char(36), due_at datetime(3) not null, status enum('scheduled','completed','cancelled') not null default 'scheduled', created_by char(36), foreign key(organization_id) references organizations(id), foreign key(recipient_user_id) references users(id), foreign key(created_by) references users(id)) engine=InnoDB;
create table notifications (id char(36) primary key, organization_id char(36) not null, user_id char(36) not null, notification_type varchar(80) not null, title varchar(255) not null, body text, deep_link varchar(500), read_at datetime(3), created_at datetime(3) not null default current_timestamp(3), foreign key(organization_id) references organizations(id), foreign key(user_id) references users(id), key ix_notification_unread(user_id,read_at,created_at)) engine=InnoDB;
create table organization_settings (organization_id char(36) primary key, company_profile json not null, collection_settings json not null, document_settings json not null, updated_by char(36), updated_at datetime(3) not null default current_timestamp(3) on update current_timestamp(3), foreign key(organization_id) references organizations(id), foreign key(updated_by) references users(id)) engine=InnoDB;

-- Table inventory is complete; add indexes/triggers in versioned migrations.
-- Implement financial totals and overlapping active lease-space validation inside transactional
-- service methods using SELECT ... FOR UPDATE; MySQL CHECK constraints alone are insufficient.
